<template>
    <section class="stem-workspace" data-testid="editor-separation" :data-state="state.status" :data-active="active" aria-label="四轨音频分离">
        <div class="stem-intro">
            <div class="intro-copy">
                <span class="section-kicker"><span class="local-dot" /> SOURCE SEPARATION</span>
                <h2>把声音，拆成四个层次<span>。</span></h2>
                <p>鼓、低音、伴奏与人声。分离留在本机，原曲与标记保持可用。</p>
                <div class="intro-actions">
                    <button v-if="!busy" class="separate-button" type="button" data-testid="editor-separate-start" :disabled="!state.trackId" @click="service.start()">
                        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v18M5 7v10M19 7v10M2 10v4M22 10v4" /></svg>
                        {{ state.result ? '重新分离' : '开始分离' }}<span aria-hidden="true">↗</span>
                    </button>
                    <button v-else class="cancel-button" type="button" data-testid="editor-separate-cancel" :disabled="['cancelling','clearing'].includes(state.status)" @click="service.cancel()">
                        {{ state.status === 'cancelling' ? '正在取消…' : state.status === 'clearing' ? '正在清理…' : '取消任务' }}
                    </button>
                    <span class="download-hint" data-testid="editor-model-download-size">
                        {{ state.storage ? state.storage.missingModelBytes ? `待下载模型 ${formatBytes(state.storage.missingModelBytes)}` : '四个模型已缓存 · 校验后复用' : '正在检查本地缓存…' }}
                    </span>
                </div>
                <span class="intro-footnote">处理可能需要较长时间，可切回标记编辑继续工作。</span>
            </div>
            <div class="separation-art" aria-hidden="true">
                <div class="source-orb"><svg viewBox="0 0 40 40"><path d="M8 18v4m6-10v16m6-21v26m6-19v12m6-9v6" /></svg><span>MIX</span></div>
                <div v-for="role in roles" :key="role" class="art-stem" :class="`art-${role}`" :style="{ '--stem-color':STEM_PRESENTATION[role].color }"><span>{{ STEM_PRESENTATION[role].short }}</span>{{ role }}</div>
                <svg class="art-connections" viewBox="0 0 340 190"><path d="M120 95H160Q180 95 180 40H228M160 95Q180 95 180 77H228M160 95Q180 95 180 114H228M160 95Q180 95 180 151H228" /></svg>
            </div>
        </div>

        <div v-if="busy && state.status !== 'clearing'" class="processing-panel" data-testid="editor-separation-progress" aria-live="polite">
            <div class="processing-heading"><span class="activity-ring" /><strong>{{ phaseLabel }}</strong><span v-if="state.role && state.status === 'running'" class="role-pill">{{ state.role }}</span><span class="processing-time">{{ clockTime((state.progress?.elapsedMs ?? 0)/1000) }}</span></div>
            <div class="phase-progress" role="progressbar" :aria-label="phaseLabel" :aria-valuemin="0" :aria-valuemax="100" :aria-valuenow="determinate ? Math.round(phaseRatio*100) : undefined"><span :class="{ indeterminate:!determinate }" :style="determinate ? {width:`${phaseRatio*100}%`} : {}" /></div>
            <div class="processing-detail"><span>{{ progressDetail }}</span><span>下载 {{ clockTime((state.progress?.downloadElapsedMs ?? 0)/1000) }} · 处理 {{ clockTime((state.progress?.processingElapsedMs ?? 0)/1000) }}</span></div>
            <div class="model-steps"><span v-for="(role,index) in roles" :key="role" :class="{ current:role === state.role, complete:index < activeRoleIndex || state.progress?.phase === 'result-verify' }" :style="{'--stem-color':STEM_PRESENTATION[role].color}"><span class="step-dot" />{{ role }}</span></div>
        </div>

        <div v-if="state.message" class="stem-message" :class="{ 'is-error':state.status === 'error' }" :role="state.status === 'error' ? 'alert' : 'status'" data-testid="editor-separation-message"><span>{{ state.message }}</span><button type="button" @click="storageOpen = true">查看缓存</button></div>

        <div class="results-heading">
            <div><span class="section-kicker">STEMS / {{ state.result ? '04' : '00' }}</span><h3>{{ state.result ? '四轨分离结果' : '声音的四个层次' }}</h3></div>
            <div class="results-tools"><span v-if="state.result" class="result-badge" data-testid="editor-separation-saved">{{ state.restored ? '已恢复本地结果' : '已保存到本地' }}</span><button type="button" class="storage-toggle" data-testid="editor-separation-storage-toggle" :aria-expanded="storageOpen" @click="storageOpen = !storageOpen">缓存设置 <span aria-hidden="true">{{ storageOpen ? '−' : '+' }}</span></button></div>
        </div>

        <div v-if="state.result" class="stem-results" data-testid="editor-stem-results">
            <div class="shared-time-labels"><span>0:00</span><span>{{ clockTime(duration/2) }}</span><span>{{ clockTime(duration) }}</span></div>
            <article v-for="(stem,index) in state.result.stems" :key="`${state.result.source.directory}-${stem.role}`" class="stem-track" :style="{'--stem-color':STEM_PRESENTATION[stem.role].color,'--entry-delay':`${index*55}ms`}" :data-testid="`editor-stem-${stem.role}`">
                <div class="stem-identity"><span class="stem-number">0{{ index+1 }}</span><div class="stem-name"><strong>{{ stem.role }}</strong><span>{{ STEM_PRESENTATION[stem.role].label }}</span></div></div>
                <div class="stem-visual" role="slider" tabindex="0" :aria-label="`${STEM_PRESENTATION[stem.role].label}概览，跳转原曲`" :aria-valuemin="0" :aria-valuemax="duration" :aria-valuenow="Math.min(duration,playback.currentTimeSeconds)" :aria-valuetext="clockTime(playback.currentTimeSeconds)" @click="seekFromPointer" @keydown="seekFromKeyboard">
                    <svg class="stem-waveform" viewBox="0 0 800 80" preserveAspectRatio="none" aria-hidden="true"><path v-for="x in [0,200,400,600,800]" :key="x" :d="`M${x} 0V80`" class="wave-grid" /><path d="M0 40H800" class="wave-zero" /><path :d="plots[stem.role]?.waveform" class="wave-fill" /></svg>
                    <svg class="stem-energy" viewBox="0 0 800 24" preserveAspectRatio="none" aria-hidden="true"><path :d="plots[stem.role]?.energy" /></svg>
                    <span class="stem-cursor" :style="{left:`${cursorRatio*100}%`}" aria-hidden="true" />
                </div>
                <div class="stem-export"><span>{{ liveEnergy(stem) }} dBFS</span><a :href="state.urls[stem.role]" :download="exportName(stem.role)" :aria-label="`导出${STEM_PRESENTATION[stem.role].label} WAV`" :data-testid="`editor-export-${stem.role}`"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 2v10m-4-4 4 4 4-4M3 12v5h14v-5" /></svg>WAV</a></div>
            </article>
            <div class="result-footnote"><span>点击波形跳转原曲 · 下方曲线为 30 Hz 能量</span><span>44.1 kHz · Stereo · Float32 WAV</span></div>
        </div>
        <div v-else class="stem-preview">
            <div v-for="(role,index) in roles" :key="role" class="preview-row" :style="{'--stem-color':STEM_PRESENTATION[role].color}"><span class="stem-number">0{{index+1}}</span><strong>{{ role }}</strong><span>{{ STEM_PRESENTATION[role].label }}</span><div class="preview-line" /><span class="preview-state">等待分离</span></div>
        </div>

        <Transition name="storage-reveal">
            <section v-if="storageOpen" class="storage-panel" data-testid="editor-separation-storage" aria-label="分离缓存设置">
                <div class="storage-summary"><div><span class="section-kicker">LOCAL STORAGE</span><h3>你的设备，你的音频</h3><p>仅清理分离缓存，工程标记保留。缓存不会自动驱逐。</p></div><div class="storage-numbers"><strong>{{ formatBytes(state.storage?.usage ?? 0) }}<small> / {{ formatBytes(Math.min(state.cacheLimit,state.storage?.quota ?? state.cacheLimit)) }}</small></strong><span>浏览器报告的站点占用 · 模型 {{ state.storage?.modelCount ?? 0 }}/4 · 结果 {{ state.storage?.resultCount ?? 0 }}<template v-if="state.storage?.orphanCount"> · 残留 {{ state.storage.orphanCount }}</template></span></div></div>
                <div class="storage-controls"><label>缓存上限 <input v-model.number="cacheGiB" type="number" min="1" max="100" step="0.5" :disabled="busy" aria-label="分离缓存上限GiB"> GiB</label><button type="button" :disabled="busy" @click="saveLimit">保存上限</button><span class="storage-spacer"/><button type="button" data-testid="editor-clear-stem-results" :disabled="busy || !state.storage" @click="pendingClear = 'results'">清理分离结果</button><button type="button" data-testid="editor-clear-stem-models" :disabled="busy || !state.storage" @click="pendingClear = 'models'">清理模型缓存</button></div>
                <p v-if="settingsMessage" role="status" class="settings-message">{{ settingsMessage }}</p>
                <div v-if="pendingClear" class="clear-confirm" role="group" aria-label="确认清理"><span>{{ pendingClear === 'results' ? '删除全部Editor分离结果及残留文件？之后可重新分离。' : '删除四个模型缓存？下次使用需要重新下载。' }}</span><button type="button" :disabled="busy" data-testid="editor-confirm-stem-clear" @click="confirmClear">确认清理</button><button type="button" @click="pendingClear = null">取消</button></div>
            </section>
        </Transition>
    </section>
</template>

<script setup lang="ts">
import { computed,onBeforeUnmount,ref,shallowRef,watch } from 'vue';
import type { PlaybackSnapshot } from '../types/audio';
import type { StemArtifact } from '../processing/kernel';
import { FT_ROLES,type StemRole } from '../processing/modelManifest';
import { useEditorSeparationService } from '../processing/editorSeparationService';
import { STEM_PRESENTATION,PHASE_LABELS,clockTime,formatBytes,stemPaths } from '../processing/presentation';
const props=defineProps<{trackId:string;trackName:string;playback:PlaybackSnapshot;active:boolean}>();
const emit=defineEmits<{seek:[seconds:number]}>();
const service=useEditorSeparationService(),state=shallowRef(service.getSnapshot()),roles=FT_ROLES;
const unsubscribe=service.subscribe(snapshot=>{state.value=snapshot;});
const storageOpen=ref(false),pendingClear=ref<'results'|'models'|null>(null),cacheGiB=ref(state.value.cacheLimit/1024**3),settingsMessage=ref('');
const busy=computed(()=>['restoring','running','cancelling','clearing'].includes(state.value.status));
const phaseLabel=computed(()=>state.value.status==='restoring'?'检查本地分离结果':state.value.status==='cancelling'?'取消并清理本次任务':PHASE_LABELS[state.value.progress?.phase??'']??'准备开始分离');
const determinate=computed(()=>state.value.status==='running'&&!!state.value.progress?.totalUnits&&!['model-load'].includes(state.value.progress.phase));
const phaseRatio=computed(()=>Math.min(1,Math.max(0,(state.value.progress?.completedUnits??0)/(state.value.progress?.totalUnits??1))));
const activeRoleIndex=computed(()=>state.value.role?roles.indexOf(state.value.role):-1);
const progressDetail=computed(()=>{const p=state.value.progress;if(!p||!determinate.value)return '完成当前阶段后继续更新';return p.phase==='model-download'||p.phase==='model-verify'?`${formatBytes(p.completedUnits)} / ${formatBytes(p.totalUnits!)}`:`本阶段 ${Math.round(phaseRatio.value*100)}%`;});
const duration=computed(()=>state.value.result?.source.descriptor.durationSeconds??props.playback.durationSeconds);
const cursorRatio=computed(()=>Math.min(1,Math.max(0,props.playback.currentTimeSeconds/(duration.value||1))));
const plots=computed(()=>Object.fromEntries(state.value.result?.stems.map(stem=>[stem.role,stemPaths(stem)])??[]) as Partial<Record<StemRole,ReturnType<typeof stemPaths>>>);
function liveEnergy(stem:StemArtifact):string{const index=Math.min(stem.energy.length-1,Math.max(0,Math.floor(props.playback.currentTimeSeconds*30)));return ((stem.energy[index]??0)*stem.energyScale+stem.energyOffset).toFixed(1);}
function exportName(role:StemRole):string{return `${props.trackName.replace(/\.[^.]+$/,'').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').slice(0,100)||'audio'}-${role}.wav`;}
function seekFromPointer(event:MouseEvent):void{const bounds=(event.currentTarget as HTMLElement).getBoundingClientRect();emit('seek',Math.min(duration.value,Math.max(0,(event.clientX-bounds.left)/bounds.width*duration.value)));}
function seekFromKeyboard(event:KeyboardEvent):void{let value=props.playback.currentTimeSeconds;const step=event.shiftKey?10:1;if(event.key==='ArrowRight')value+=step;else if(event.key==='ArrowLeft')value-=step;else if(event.key==='Home')value=0;else if(event.key==='End')value=duration.value;else return;event.preventDefault();emit('seek',Math.min(duration.value,Math.max(0,value)));}
function saveLimit():void{try{service.setCacheLimit(cacheGiB.value*1024**3);settingsMessage.value='缓存上限已保存，实际可用空间仍受浏览器限制。';}catch(error){settingsMessage.value=error instanceof Error?error.message:'无法保存上限。';}}
function confirmClear():void{const kind=pendingClear.value;pendingClear.value=null;if(kind)void service.clear(kind);}
watch(()=>props.trackId,id=>{void service.bind(id);},{immediate:true});
onBeforeUnmount(()=>{unsubscribe();if(service.getSnapshot().trackId===props.trackId)void service.bind(null);});
</script>

