px solid #577663;background:radial-gradient(circle,#213f2c,#102319);box-shadow:0 0 0 14px #a7deb607,0 0 0 30px #a7deb603;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:1}.source-orb svg{height:31px;width:31px;fill:none;stroke:#b7e9ce;stroke-width:1.5;stroke-linecap:round}.source-orb>span{font-size:8px;letter-spacing:.16em;color:#90b69d}.art-stem{position:absolute;left:229px;display:flex;align-items:center;gap:9px;color:#c0ccc4;font-size:10px;z-index:1}.art-stem>span{display:grid;place-items:center;width:24px;height:24px;border-radius:5px;border:1px solid color-mix(in srgb,var(--stem-color) 30%,transparent);color:var(--stem-color);background:color-mix(in srgb,var(--stem-color) 6%,#0a1510);font:9px ui-monospace,monospace}.art-drums{top:28px}.art-bass{top:65px}.art-other{top:102px}.art-vocals{top:139px}.art-connections{position:absolute;inset:0;width:100%;height:100%;fill:none;stroke:#42624e;stroke-width:1;opacity:.7}.processing-panel{margin-top:12px;border:1px solid #2f4b3c;background:#0d1b13;padding:18px 22px;border-radius:10px}.processing-heading{display:flex;align-items:center;gap:10px;font-size:12px}.activity-ring{width:12px;height:12px;border:1px solid #355a43;border-top-color:#9fdfb7;border-radius:50%;animation:rotate 1.1s linear infinite}.processing-heading strong{font-weight:500}.role-pill{font:10px ui-monospace,monospace;color:#a8c4b3;border:1px solid #34513e;padding:2px 7px;border-radius:4px}.processing-time{margin-left:auto;color:#b6c5bd;font:12px ui-monospace,monospace}.phase-progress{height:3px;background:#20342a;border-radius:2px;overflow:hidden;margin-top:16px}.phase-progress>span{display:block;height:100%;background:#aadfbd;transition:width .25s}.phase-progress>.indeterminate{width:25%;animation:scan 1.7s ease-in-out infinite}.processing-detail{display:flex;justify-content:space-between;gap:12px;margin-top:9px;color:#8ba191;font-size:10px;font-variant-numeric:tabular-nums}.model-steps{display:flex;gap:30px;margin-t